import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Modules are Evaluated Environments","description":"","frontmatter":{"title":"Modules are Evaluated Environments","type":"adr","date":"2026-09-02T00:00:00.000Z","status":"proposed","status_note":"Proposed — modules are environments evaluated from source."},"headers":[],"relativePath":"handl/project/adrs/0049-modules-are-evaluated-environments.md","filePath":"vendored/handl/project/adrs/0049-modules-are-evaluated-environments.md"}`),a={name:`handl/project/adrs/0049-modules-are-evaluated-environments.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0049-modules-are-evaluated-environments" tabindex="-1">ADR-0049: Modules are Evaluated Environments <a class="header-anchor" href="#adr-0049-modules-are-evaluated-environments" aria-label="Permalink to “ADR-0049: Modules are Evaluated Environments”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong>Environments are first-class values</strong> — a module is the environment its source evaluates to.</li><li><strong><code>import</code> / <code>export</code> / <code>module</code> / <code>field-access</code> move off <code>Foreign</code></strong> and become language-level operations over environments.</li><li><strong>The import resolver is the loader</strong> — resolution and evaluation are one pipeline, not two mechanisms.</li><li><strong>The stdlib is <code>.hnl</code> files</strong> evaluated like user modules.</li><li><strong>The module system is written in handl</strong>, on top of the environment value.</li><li><strong>Per-language module systems</strong>: each language defines its own import/export rules over the same environment primitive.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>Module operations were host calls, so the language could not define its own module system and the stdlib needed a separate path. Environments as values dissolve most of the machinery ADR-0048 proposed and make modules ordinary data.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>A <code>Module</code> value type plus registry</strong> — ADR-0048&#39;s rejected design; an environment is enough.</li><li><strong>Host-only module ops</strong> — they are language operations.</li><li><strong>One module system for every language</strong> — each language defines its own.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Modules are environments; import is resolve + evaluate.</li><li>The stdlib shares the mechanism.</li><li>Each language owns its import/export rules.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>handl-runtime/</code> — environment values and the resolver.</li><li><code>kit-prelude-lang/</code> — the <code>.hnl</code> stdlib.</li><li>Module-system tests per language.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>+Environment values, the four operations, resolver and per-language systems: +<a href="./../design/0049-modules-are-evaluated-environments.html"><code>design/0049-modules-are-evaluated-environments.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};